-- STAGING ONLY. Apply after 211/212; no legacy rows are reinterpreted as earned OT.
ALTER TABLE ty_leave_lot ADD COLUMN effective_expires_on date;
UPDATE ty_leave_lot SET effective_expires_on=expires_on;
ALTER TABLE ty_leave_lot ADD COLUMN advanced numeric(18,4) NOT NULL DEFAULT 0 CHECK(advanced>=0);
ALTER TABLE ty_leave_lot ADD COLUMN transferred_in numeric(18,4) NOT NULL DEFAULT 0 CHECK(transferred_in>=0);
ALTER TABLE ty_leave_lot ADD COLUMN transferred_out numeric(18,4) NOT NULL DEFAULT 0 CHECK(transferred_out>=0);
ALTER TABLE ty_leave_lot ADD COLUMN converted numeric(18,4) NOT NULL DEFAULT 0 CHECK(converted>=0);
ALTER TABLE ty_leave_lot ADD COLUMN source_protection text NOT NULL DEFAULT 'none' CHECK(source_protection IN('none','compensation','advance'));
DO $$ DECLARE c record;BEGIN
 FOR c IN SELECT conname FROM pg_constraint WHERE conrelid='ty_leave_lot'::regclass AND contype='c' AND pg_get_constraintdef(oid) LIKE '%granted >=%' AND pg_get_constraintdef(oid) LIKE '%held + allocated%' LOOP
  EXECUTE format('ALTER TABLE ty_leave_lot DROP CONSTRAINT %I',c.conname);
 END LOOP;END;$$;
ALTER TABLE ty_leave_lot ADD CONSTRAINT ck_ty_leave_lifecycle_balance CHECK
 (granted+advanced+transferred_in>=held+allocated+taken+cash_reserved+expired+converted+transferred_out);

CREATE TABLE ty_leave_lifecycle_proposal (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,account_id bigint NOT NULL REFERENCES ty_leave_account(id),
 kind text NOT NULL CHECK(kind IN('extend','carry','recurring','overtime_basis','overtime_allocate','comp_cash','advance','advance_repay','cash_qualification','annual_cash')),
 stable_key text NOT NULL,revision integer NOT NULL CHECK(revision>0),payload jsonb NOT NULL,payload_hash text NOT NULL,
 baseline_revision bigint NOT NULL,quantity numeric(18,4),evidence_ref text NOT NULL CHECK(length(btrim(evidence_ref))>=4),
 approval_route text NOT NULL DEFAULT 'direct' CHECK(approval_route IN('direct','workflow')),
 workflow_instance_id bigint,execution_actor_id bigint,
 created_by bigint NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','rejected','cancelled')),
 approved_by bigint,approved_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 CHECK(status<>'approved' OR(approved_by IS NOT NULL AND approved_by<>created_by AND approved_at IS NOT NULL)),
 UNIQUE(account_id,kind,stable_key,revision)
);
CREATE TABLE ty_leave_credit_origin (
 lot_id bigint PRIMARY KEY REFERENCES ty_leave_lot(id),root_key text NOT NULL,
 kind text NOT NULL CHECK(kind IN('earned_overtime','carry','advance','verified_external_earned')),
 parent_lot_id bigint REFERENCES ty_leave_lot(id),source_key text NOT NULL,
 proposal_id bigint NOT NULL REFERENCES ty_leave_lifecycle_proposal(id)
);
CREATE TABLE ty_leave_lifecycle_ledger (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,proposal_id bigint NOT NULL REFERENCES ty_leave_lifecycle_proposal(id),
 lot_id bigint NOT NULL REFERENCES ty_leave_lot(id),event_key text NOT NULL,
 kind text NOT NULL CHECK(kind IN('carry_in','carry_out','advance','repay_source','repay_loan','cash_hold','cash_release','cash_convert','comp_cash')),
 quantity numeric(18,4) NOT NULL CHECK(quantity>0),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(proposal_id,event_key)
);
CREATE TABLE ty_leave_extension (
 proposal_id bigint PRIMARY KEY REFERENCES ty_leave_lifecycle_proposal(id),lot_id bigint NOT NULL REFERENCES ty_leave_lot(id),
 previous_expires_on date,new_expires_on date NOT NULL,legal_route text NOT NULL,
 CHECK(previous_expires_on IS NULL OR new_expires_on>previous_expires_on)
);
CREATE TABLE ty_leave_transfer (
 proposal_id bigint PRIMARY KEY REFERENCES ty_leave_lifecycle_proposal(id),from_lot_id bigint NOT NULL REFERENCES ty_leave_lot(id),
 to_lot_id bigint NOT NULL UNIQUE REFERENCES ty_leave_lot(id),quantity numeric(18,4) NOT NULL CHECK(quantity>0),
 CHECK(from_lot_id<>to_lot_id)
);
CREATE TABLE ty_leave_recurring_authorization (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,proposal_id bigint NOT NULL UNIQUE REFERENCES ty_leave_lifecycle_proposal(id),
 account_id bigint NOT NULL REFERENCES ty_leave_account(id),stable_key text NOT NULL,revision integer NOT NULL,
 scheme_id bigint NOT NULL REFERENCES ty_leave_scheme(id),employment_id bigint NOT NULL REFERENCES ty_employment(id),
 valid_from date NOT NULL,valid_to date NOT NULL,slots jsonb NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','superseded','suspended')),
 CHECK(valid_to>valid_from),UNIQUE(account_id,stable_key,revision)
);
CREATE TABLE ty_leave_recurring_occurrence (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,account_id bigint NOT NULL REFERENCES ty_leave_account(id),
 root_key text NOT NULL,authorization_id bigint NOT NULL REFERENCES ty_leave_recurring_authorization(id),
 source_revision integer NOT NULL,work_date date NOT NULL,slot_key text NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,
 status text NOT NULL CHECK(status IN('candidate','requested','withdrawn','needs_replacement')),
 request_id bigint REFERENCES ty_leave_request(id),last_seen_revision integer NOT NULL,
 request_sequence integer NOT NULL DEFAULT 0 CHECK(request_sequence>=0),
 CHECK(ends_at>starts_at),UNIQUE(account_id,root_key)
);
CREATE TABLE ty_leave_recurring_request_link (
 request_id bigint PRIMARY KEY REFERENCES ty_leave_request(id),occurrence_id bigint NOT NULL REFERENCES ty_leave_recurring_occurrence(id),
 authorization_id bigint NOT NULL REFERENCES ty_leave_recurring_authorization(id),sequence integer NOT NULL CHECK(sequence>0),
 approval_mode text NOT NULL CHECK(approval_mode IN('inherited_authorization','requires_review')),
 inherited_approved_by bigint,original_requester_id bigint NOT NULL,
 execution_actor_id bigint NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(occurrence_id,sequence),
 CHECK((approval_mode='inherited_authorization')=(inherited_approved_by IS NOT NULL))
);
CREATE TABLE ty_leave_overtime_source (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,account_id bigint NOT NULL REFERENCES ty_leave_account(id),
 relationship_id bigint NOT NULL REFERENCES ty_leave_relationship(id),
 source_kind text NOT NULL CHECK(source_kind IN('native_confirmed','external_verified')),
 source_namespace text NOT NULL,work_fact_key text NOT NULL,latest_revision integer NOT NULL,
 classification text NOT NULL CHECK(classification IN('CN_WEEKDAY','CN_REST','CN_HOLIDAY','HK_CONTRACT')),
 verified_minutes numeric(18,4) NOT NULL CHECK(verified_minutes>0),
 initial_cash_basis numeric(18,4) NOT NULL CHECK(initial_cash_basis>=0),initial_comp_basis numeric(18,4) NOT NULL CHECK(initial_comp_basis>=0),
 unknown_hold_basis numeric(18,4) NOT NULL CHECK(unknown_hold_basis>=0),
 cash_basis numeric(18,4) NOT NULL CHECK(cash_basis>=0),comp_basis numeric(18,4) NOT NULL CHECK(comp_basis>=0),
 comp_generated numeric(18,4) NOT NULL DEFAULT 0 CHECK(comp_generated>=0),
 comp_returned_basis numeric(18,4) NOT NULL DEFAULT 0 CHECK(comp_returned_basis>=0),
 ratio_numerator integer NOT NULL CHECK(ratio_numerator>0),ratio_denominator integer NOT NULL CHECK(ratio_denominator>0),
 currency text NOT NULL CHECK(currency IN('CNY','HKD')),cash_unit_rate numeric(24,10) NOT NULL CHECK(cash_unit_rate>=0),
 allow_comp boolean NOT NULL,allow_comp_cash boolean NOT NULL,pricing_ref text NOT NULL,
 CHECK(cash_basis>=initial_cash_basis AND comp_basis>=0),
 CHECK(cash_basis+comp_basis+unknown_hold_basis<=verified_minutes),
 CHECK(allow_comp OR comp_basis=0),
 UNIQUE(account_id,source_kind,source_namespace,work_fact_key),UNIQUE(relationship_id,source_kind,source_namespace,work_fact_key)
);
CREATE TABLE ty_leave_overtime_revision (
 source_id bigint NOT NULL REFERENCES ty_leave_overtime_source(id),revision integer NOT NULL,
 proposal_id bigint NOT NULL UNIQUE REFERENCES ty_leave_lifecycle_proposal(id),facts jsonb NOT NULL,
 PRIMARY KEY(source_id,revision)
);
CREATE TABLE ty_leave_overtime_allocation (
 proposal_id bigint PRIMARY KEY REFERENCES ty_leave_lifecycle_proposal(id),source_id bigint NOT NULL REFERENCES ty_leave_overtime_source(id),
 cash_basis_delta numeric(18,4) NOT NULL CHECK(cash_basis_delta>=0),comp_basis_delta numeric(18,4) NOT NULL CHECK(comp_basis_delta>=0),
 comp_quantity_delta numeric(18,4) NOT NULL CHECK(comp_quantity_delta>=0),lot_id bigint REFERENCES ty_leave_lot(id)
);
CREATE TABLE ty_leave_comp_cash_conversion (
 proposal_id bigint PRIMARY KEY REFERENCES ty_leave_lifecycle_proposal(id),source_id bigint NOT NULL REFERENCES ty_leave_overtime_source(id),
 lot_id bigint NOT NULL REFERENCES ty_leave_lot(id),quota_quantity numeric(18,4) NOT NULL CHECK(quota_quantity>0),
 basis_minutes numeric(18,4) NOT NULL CHECK(basis_minutes>0)
);
CREATE TABLE ty_leave_advance (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,proposal_id bigint NOT NULL UNIQUE REFERENCES ty_leave_lifecycle_proposal(id),
 account_id bigint NOT NULL REFERENCES ty_leave_account(id),lot_id bigint NOT NULL UNIQUE REFERENCES ty_leave_lot(id),
 original_quantity numeric(18,4) NOT NULL CHECK(original_quantity>0),outstanding numeric(18,4) NOT NULL CHECK(outstanding>=0),
 due_on date NOT NULL,status text NOT NULL CHECK(status IN('open','repaid','exit_review')),
 CHECK(outstanding<=original_quantity),CHECK((status='repaid')=(outstanding=0))
);
CREATE TABLE ty_leave_advance_repayment (
 advance_id bigint NOT NULL REFERENCES ty_leave_advance(id),operation_key text NOT NULL,source_lot_id bigint NOT NULL REFERENCES ty_leave_lot(id),
 quantity numeric(18,4) NOT NULL CHECK(quantity>0),proposal_id bigint NOT NULL REFERENCES ty_leave_lifecycle_proposal(id),
 created_by bigint NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(advance_id,operation_key)
);
CREATE TABLE ty_leave_cash_qualification (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,proposal_id bigint NOT NULL UNIQUE REFERENCES ty_leave_lifecycle_proposal(id),
 account_id bigint NOT NULL REFERENCES ty_leave_account(id),entitlement_year integer NOT NULL,
 root_key text NOT NULL,revision integer NOT NULL,
 route text NOT NULL CHECK(route IN('CN_UNTAKEN_CONSENT','CN_TERMINATION','HK_IN_SERVICE_EXCESS10','HK_TERMINATION_DETERMINED','CONTRACTUAL')),
 maximum_days numeric(18,4) NOT NULL CHECK(maximum_days>=0),historical_cash_days numeric(18,4) NOT NULL CHECK(historical_cash_days>=0),
 reserved_days numeric(18,4) NOT NULL DEFAULT 0 CHECK(reserved_days>=0),converted_days numeric(18,4) NOT NULL DEFAULT 0 CHECK(converted_days>=0),
 currency text NOT NULL CHECK(currency IN('CNY','HKD')),daily_rate_numerator numeric(30,0) NOT NULL CHECK(daily_rate_numerator>=0),
 daily_rate_denominator numeric(30,0) NOT NULL CHECK(daily_rate_denominator>0),normal_daily_covered numeric(24,10) NOT NULL CHECK(normal_daily_covered>=0),
 facts jsonb NOT NULL,status text NOT NULL CHECK(status IN('approved','superseded')),
 CHECK(historical_cash_days+reserved_days+converted_days<=maximum_days),UNIQUE(account_id,root_key,revision)
);
CREATE TABLE ty_leave_cash_reservation (
 proposal_id bigint PRIMARY KEY REFERENCES ty_leave_lifecycle_proposal(id),qualification_id bigint NOT NULL REFERENCES ty_leave_cash_qualification(id),
 lot_id bigint NOT NULL REFERENCES ty_leave_lot(id),quantity numeric(18,4) NOT NULL CHECK(quantity>0),
 gross_target numeric(18,4) NOT NULL CHECK(gross_target>=0),normal_covered numeric(18,4) NOT NULL CHECK(normal_covered>=0),
 status text NOT NULL CHECK(status IN('held','converted','released')),CHECK(normal_covered<=gross_target)
);
CREATE TABLE ty_leave_lifecycle_cash_obligation (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,account_id bigint NOT NULL REFERENCES ty_leave_account(id),
 root_key text NOT NULL,currency text NOT NULL CHECK(currency IN('CNY','HKD')),revision integer NOT NULL,
 gross_target numeric(18,4) NOT NULL CHECK(gross_target>=0),normal_covered numeric(18,4) NOT NULL CHECK(normal_covered>=0),
 gross_numerator text NOT NULL CHECK(gross_numerator ~ '^[0-9]+$' AND length(gross_numerator)<=30000),
 gross_denominator text NOT NULL CHECK(gross_denominator ~ '^[1-9][0-9]*$' AND length(gross_denominator)<=30000),
 status text NOT NULL DEFAULT 'confirmed_source' CHECK(status='confirmed_source'),
 CHECK(normal_covered<=gross_target),UNIQUE(account_id,root_key)
);
CREATE TABLE ty_leave_lifecycle_cash_revision (
 obligation_id bigint NOT NULL REFERENCES ty_leave_lifecycle_cash_obligation(id),revision integer NOT NULL,
 proposal_id bigint NOT NULL UNIQUE REFERENCES ty_leave_lifecycle_proposal(id),
 gross_target numeric(18,4) NOT NULL,normal_covered numeric(18,4) NOT NULL,
 gross_numerator text NOT NULL,gross_denominator text NOT NULL,
 PRIMARY KEY(obligation_id,revision)
);
CREATE TABLE ty_leave_lifecycle_review (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,account_id bigint NOT NULL REFERENCES ty_leave_account(id),
 stable_key text NOT NULL,kind text NOT NULL,payload jsonb NOT NULL,created_by bigint NOT NULL,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(account_id,stable_key)
);
CREATE TABLE ty_leave_lifecycle_lot_baseline (
 lot_id bigint PRIMARY KEY REFERENCES ty_leave_lot(id),cash_reserved numeric(18,4) NOT NULL CHECK(cash_reserved>=0)
);
INSERT INTO ty_leave_lifecycle_lot_baseline SELECT id,cash_reserved FROM ty_leave_lot;
CREATE TRIGGER trg_ty_leave_life_baseline_immutable BEFORE UPDATE OR DELETE ON ty_leave_lifecycle_lot_baseline FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_immutable();

CREATE FUNCTION fn_ty_leave_lifecycle_post() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE l ty_leave_lot%ROWTYPE;p ty_leave_lifecycle_proposal%ROWTYPE;BEGIN
 SELECT * INTO p FROM ty_leave_lifecycle_proposal WHERE id=NEW.proposal_id;
 SELECT * INTO l FROM ty_leave_lot WHERE id=NEW.lot_id FOR UPDATE;
 IF p.account_id<>l.account_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='生命周期流水与账户不一致';END IF;
 UPDATE ty_leave_lot SET
  advanced=advanced+CASE NEW.kind WHEN 'advance' THEN NEW.quantity WHEN 'repay_loan' THEN -NEW.quantity ELSE 0 END,
  transferred_in=transferred_in+CASE WHEN NEW.kind IN('carry_in','repay_loan') THEN NEW.quantity ELSE 0 END,
  transferred_out=transferred_out+CASE WHEN NEW.kind IN('carry_out','repay_source') THEN NEW.quantity ELSE 0 END,
  cash_reserved=cash_reserved+CASE NEW.kind WHEN 'cash_hold' THEN NEW.quantity WHEN 'cash_release' THEN -NEW.quantity WHEN 'cash_convert' THEN -NEW.quantity ELSE 0 END,
  converted=converted+CASE WHEN NEW.kind IN('cash_convert','comp_cash') THEN NEW.quantity ELSE 0 END WHERE id=l.id;
 UPDATE ty_leave_account SET revision=revision+1 WHERE id=l.account_id;RETURN NEW;END;$$;
CREATE TRIGGER trg_ty_leave_lifecycle_post AFTER INSERT ON ty_leave_lifecycle_ledger FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_lifecycle_post();
CREATE TRIGGER trg_ty_leave_lifecycle_ledger_immutable BEFORE UPDATE OR DELETE ON ty_leave_lifecycle_ledger FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_immutable();
CREATE TRIGGER trg_ty_leave_credit_origin_immutable BEFORE UPDATE OR DELETE ON ty_leave_credit_origin FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_immutable();
CREATE TRIGGER trg_ty_leave_overtime_revision_immutable BEFORE UPDATE OR DELETE ON ty_leave_overtime_revision FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_immutable();
CREATE TRIGGER trg_ty_leave_cash_revision_immutable BEFORE UPDATE OR DELETE ON ty_leave_lifecycle_cash_revision FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_immutable();
CREATE TRIGGER trg_ty_leave_transfer_immutable BEFORE UPDATE OR DELETE ON ty_leave_transfer FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_immutable();
CREATE TRIGGER trg_ty_leave_extension_immutable BEFORE UPDATE OR DELETE ON ty_leave_extension FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_immutable();
CREATE TRIGGER trg_ty_leave_repayment_immutable BEFORE UPDATE OR DELETE ON ty_leave_advance_repayment FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_immutable();
CREATE TRIGGER trg_ty_leave_comp_cash_immutable BEFORE UPDATE OR DELETE ON ty_leave_comp_cash_conversion FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_immutable();
CREATE TRIGGER trg_ty_leave_recurring_link_immutable BEFORE UPDATE OR DELETE ON ty_leave_recurring_request_link FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_immutable();

CREATE FUNCTION fn_ty_leave_lifecycle_reference() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_p ty_leave_lifecycle_proposal%ROWTYPE;v_l ty_leave_lot%ROWTYPE;v_to ty_leave_lot%ROWTYPE;v_c ty_leave_cash_qualification%ROWTYPE;v_a ty_leave_advance%ROWTYPE;v_s ty_leave_overtime_source%ROWTYPE;v_account ty_leave_account%ROWTYPE;BEGIN
 IF TG_TABLE_NAME='ty_leave_overtime_source' THEN
  SELECT * INTO v_account FROM ty_leave_account WHERE id=NEW.account_id;
  IF NEW.relationship_id<>v_account.relationship_id OR v_account.unit<>'minute' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='加班事实须绑定一致的实际关系分钟账户';END IF;RETURN NEW;
 END IF;
 SELECT * INTO v_p FROM ty_leave_lifecycle_proposal WHERE id=NEW.proposal_id;
 IF TG_TABLE_NAME='ty_leave_lifecycle_ledger' THEN
  SELECT * INTO v_l FROM ty_leave_lot WHERE id=NEW.lot_id;
  IF v_l.account_id<>v_p.account_id OR NEW.quantity<>v_p.quantity OR
   (NEW.kind IN('carry_in','carry_out') AND v_p.kind<>'carry') OR(NEW.kind='advance' AND v_p.kind<>'advance') OR
   (NEW.kind IN('repay_source','repay_loan') AND v_p.kind<>'advance_repay') OR(NEW.kind IN('cash_hold','cash_release','cash_convert') AND v_p.kind<>'annual_cash') OR(NEW.kind='comp_cash' AND v_p.kind<>'comp_cash') OR
   (NEW.kind NOT IN('cash_hold','cash_release') AND v_p.status<>'approved') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='生命周期流水种类、批准状态或量不匹配';END IF;
 ELSIF TG_TABLE_NAME='ty_leave_transfer' THEN
  SELECT * INTO v_l FROM ty_leave_lot WHERE id=NEW.from_lot_id;SELECT * INTO v_to FROM ty_leave_lot WHERE id=NEW.to_lot_id;
  IF v_p.kind<>'carry' OR v_p.status<>'approved' OR v_l.account_id<>v_p.account_id OR v_to.account_id<>v_p.account_id OR v_l.entitlement_year<>v_to.entitlement_year OR v_l.statutory<>v_to.statutory OR NEW.quantity<>v_p.quantity THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='结转必须同权益账户原年度且经批准';END IF;
 ELSIF TG_TABLE_NAME='ty_leave_extension' THEN
  SELECT * INTO v_l FROM ty_leave_lot WHERE id=NEW.lot_id;
  IF v_p.kind<>'extend' OR v_p.status<>'approved' OR v_l.account_id<>v_p.account_id OR NEW.new_expires_on<>((v_p.payload->>'new_expires_on')::date) OR NEW.previous_expires_on IS DISTINCT FROM coalesce(v_l.effective_expires_on,v_l.expires_on) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='延期必须对应已批准原期限和新期限';END IF;
 ELSIF TG_TABLE_NAME='ty_leave_cash_reservation' THEN
  SELECT * INTO v_l FROM ty_leave_lot WHERE id=NEW.lot_id;SELECT * INTO v_c FROM ty_leave_cash_qualification WHERE id=NEW.qualification_id;
  IF v_p.kind<>'annual_cash' OR v_l.account_id<>v_p.account_id OR v_c.account_id<>v_p.account_id OR v_c.entitlement_year<>v_l.entitlement_year OR NEW.quantity<>v_p.quantity OR NEW.gross_target<>round(NEW.quantity*v_c.daily_rate_numerator/v_c.daily_rate_denominator,4) OR NEW.normal_covered<>round(NEW.quantity*v_c.normal_daily_covered,4) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='现金量、权益年度、资格或计价不匹配';END IF;
 ELSIF TG_TABLE_NAME='ty_leave_advance' THEN
  SELECT * INTO v_l FROM ty_leave_lot WHERE id=NEW.lot_id;
  IF v_p.kind<>'advance' OR v_p.status<>'approved' OR NEW.account_id<>v_p.account_id OR v_l.account_id<>v_p.account_id OR v_l.granted<>0 OR NEW.original_quantity<>v_p.quantity THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='预支必须独立于真实已得加班';END IF;
 ELSIF TG_TABLE_NAME='ty_leave_advance_repayment' THEN
  SELECT * INTO v_a FROM ty_leave_advance WHERE id=NEW.advance_id;SELECT * INTO v_l FROM ty_leave_lot WHERE id=NEW.source_lot_id;
  IF v_p.kind<>'advance_repay' OR v_p.status<>'approved' OR v_a.account_id<>v_p.account_id OR v_l.account_id<>v_p.account_id OR NEW.quantity<>v_p.quantity OR NOT EXISTS(SELECT 1 FROM ty_leave_credit_origin WHERE lot_id=v_l.id AND kind IN('earned_overtime','carry','verified_external_earned')) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='清偿须用同关系真实已得权益并经批准';END IF;
 ELSIF TG_TABLE_NAME IN('ty_leave_overtime_allocation','ty_leave_comp_cash_conversion') THEN
  SELECT * INTO v_s FROM ty_leave_overtime_source WHERE id=NEW.source_id;
  IF v_s.account_id<>v_p.account_id OR v_p.status<>'approved' OR(TG_TABLE_NAME='ty_leave_overtime_allocation' AND v_p.kind<>'overtime_allocate') OR(TG_TABLE_NAME='ty_leave_comp_cash_conversion' AND v_p.kind<>'comp_cash') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='补偿分配须来自同账户已核来源';END IF;
  IF NEW.lot_id IS NOT NULL THEN SELECT * INTO v_l FROM ty_leave_lot WHERE id=NEW.lot_id;IF v_l.account_id<>v_p.account_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='补偿权益批次与来源实际关系不一致';END IF;END IF;
 ELSIF TG_TABLE_NAME='ty_leave_credit_origin' THEN
  SELECT * INTO v_l FROM ty_leave_lot WHERE id=NEW.lot_id;
  IF v_l.account_id<>v_p.account_id OR v_p.status<>'approved' OR(NEW.kind='earned_overtime' AND v_p.kind<>'overtime_allocate')OR(NEW.kind='carry' AND v_p.kind<>'carry')OR(NEW.kind='advance' AND v_p.kind<>'advance')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='权益血缘须对应同账户已批准来源';END IF;
 END IF;RETURN NEW;END;$$;
CREATE TRIGGER trg_ty_leave_life_ledger_reference BEFORE INSERT ON ty_leave_lifecycle_ledger FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_lifecycle_reference();
CREATE TRIGGER trg_ty_leave_transfer_reference BEFORE INSERT ON ty_leave_transfer FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_lifecycle_reference();
CREATE TRIGGER trg_ty_leave_extension_reference BEFORE INSERT ON ty_leave_extension FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_lifecycle_reference();
CREATE TRIGGER trg_ty_leave_cash_res_reference BEFORE INSERT ON ty_leave_cash_reservation FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_lifecycle_reference();
CREATE TRIGGER trg_ty_leave_advance_reference BEFORE INSERT ON ty_leave_advance FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_lifecycle_reference();
CREATE TRIGGER trg_ty_leave_repayment_reference BEFORE INSERT ON ty_leave_advance_repayment FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_lifecycle_reference();
CREATE TRIGGER trg_ty_leave_ot_source_reference BEFORE INSERT OR UPDATE ON ty_leave_overtime_source FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_lifecycle_reference();
CREATE TRIGGER trg_ty_leave_ot_allocation_reference BEFORE INSERT ON ty_leave_overtime_allocation FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_lifecycle_reference();
CREATE TRIGGER trg_ty_leave_comp_conversion_reference BEFORE INSERT ON ty_leave_comp_cash_conversion FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_lifecycle_reference();
CREATE TRIGGER trg_ty_leave_credit_origin_reference BEFORE INSERT ON ty_leave_credit_origin FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_lifecycle_reference();
CREATE FUNCTION fn_ty_leave_origin_protection()RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 UPDATE ty_leave_lot SET source_protection=CASE WHEN NEW.kind='earned_overtime'OR NEW.root_key LIKE 'ot:%'THEN 'compensation'WHEN NEW.kind='advance'OR NEW.root_key LIKE 'advance:%'THEN 'advance'ELSE 'none'END WHERE id=NEW.lot_id;RETURN NEW;END;$$;
CREATE TRIGGER trg_ty_leave_origin_protection AFTER INSERT ON ty_leave_credit_origin FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_origin_protection();

CREATE FUNCTION fn_ty_leave_lifecycle_document_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' OR OLD.status<>'pending' OR NEW.status NOT IN('approved','rejected','cancelled') OR
 (to_jsonb(NEW)-ARRAY['status','approved_by','approved_at','workflow_instance_id','execution_actor_id']) IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['status','approved_by','approved_at','workflow_instance_id','execution_actor_id']) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='生命周期批准事实不可改写';END IF;
 RETURN NEW;END;$$;
CREATE TRIGGER trg_ty_leave_lifecycle_document BEFORE UPDATE OR DELETE ON ty_leave_lifecycle_proposal FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_lifecycle_document_guard();

-- Paired transfer/repayment and cash lifecycle must agree at transaction end.
CREATE FUNCTION fn_ty_leave_lifecycle_conservation() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE p ty_leave_lifecycle_proposal%ROWTYPE;rid bigint;BEGIN
 IF TG_TABLE_NAME='ty_leave_lifecycle_proposal' THEN rid:=NEW.id;ELSE rid:=NEW.proposal_id;END IF;
 SELECT * INTO p FROM ty_leave_lifecycle_proposal WHERE id=rid;
 IF p.status='approved' THEN
  IF p.kind='carry' AND (NOT EXISTS(SELECT 1 FROM ty_leave_transfer WHERE proposal_id=rid AND quantity=p.quantity) OR (SELECT count(*) FROM ty_leave_lifecycle_ledger WHERE proposal_id=rid)<>2 OR (SELECT coalesce(sum(quantity),0)FROM ty_leave_lifecycle_ledger WHERE proposal_id=rid AND kind='carry_in')<>p.quantity OR(SELECT coalesce(sum(quantity),0)FROM ty_leave_lifecycle_ledger WHERE proposal_id=rid AND kind='carry_out')<>p.quantity)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='结转必须成对且净量守恒';END IF;
  IF p.kind='advance' AND (NOT EXISTS(SELECT 1 FROM ty_leave_advance WHERE proposal_id=rid AND original_quantity=p.quantity) OR(SELECT count(*)FROM ty_leave_lifecycle_ledger WHERE proposal_id=rid AND kind='advance')<>1 OR(SELECT coalesce(sum(quantity),0)FROM ty_leave_lifecycle_ledger WHERE proposal_id=rid AND kind='advance')<>p.quantity)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='预支授权、债务和供给必须唯一对应';END IF;
  IF p.kind='advance_repay' AND(NOT EXISTS(SELECT 1 FROM ty_leave_advance_repayment WHERE proposal_id=rid AND quantity=p.quantity) OR(SELECT count(*)FROM ty_leave_lifecycle_ledger WHERE proposal_id=rid)<>2 OR(SELECT coalesce(sum(quantity),0)FROM ty_leave_lifecycle_ledger WHERE proposal_id=rid AND kind='repay_source')<>p.quantity OR(SELECT coalesce(sum(quantity),0)FROM ty_leave_lifecycle_ledger WHERE proposal_id=rid AND kind='repay_loan')<>p.quantity)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='预支清偿双方和债务量不守恒';END IF;
  IF p.kind='extend' AND NOT EXISTS(SELECT 1 FROM ty_leave_extension WHERE proposal_id=rid)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='延期批准缺少实际接续记录';END IF;
  IF p.kind='recurring' AND NOT EXISTS(SELECT 1 FROM ty_leave_recurring_authorization WHERE proposal_id=rid)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='周期批准缺少授权记录';END IF;
  IF p.kind='overtime_basis' AND NOT EXISTS(SELECT 1 FROM ty_leave_overtime_revision WHERE proposal_id=rid)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='加班核定缺少原事实修订';END IF;
  IF p.kind='overtime_allocate' AND NOT EXISTS(SELECT 1 FROM ty_leave_overtime_allocation o WHERE o.proposal_id=rid AND(o.comp_quantity_delta=0 OR EXISTS(SELECT 1 FROM ty_leave_event e WHERE e.lot_id=o.lot_id AND e.delta=o.comp_quantity_delta AND(e.payload->>'lifecycle_proposal_id')::bigint=rid)))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='加班分配和调休真实授予不对应';END IF;
  IF p.kind='comp_cash' AND(NOT EXISTS(SELECT 1 FROM ty_leave_comp_cash_conversion WHERE proposal_id=rid AND quota_quantity=p.quantity)OR(SELECT coalesce(sum(quantity),0)FROM ty_leave_lifecycle_ledger WHERE proposal_id=rid AND kind='comp_cash')<>p.quantity)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='调休回转基础和权益耗用不对应';END IF;
  IF p.kind='cash_qualification' AND NOT EXISTS(SELECT 1 FROM ty_leave_cash_qualification WHERE proposal_id=rid)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='现金资格批准缺少核定记录';END IF;
 END IF;
 IF p.kind='annual_cash' THEN
  IF NOT EXISTS(SELECT 1 FROM ty_leave_cash_reservation c WHERE c.proposal_id=rid AND c.quantity=p.quantity AND c.status=CASE p.status WHEN 'pending' THEN 'held' WHEN 'approved' THEN 'converted' ELSE 'released' END)OR(SELECT coalesce(sum(quantity),0)FROM ty_leave_lifecycle_ledger WHERE proposal_id=rid AND kind='cash_hold')<>p.quantity OR(p.status='approved' AND((SELECT coalesce(sum(quantity),0)FROM ty_leave_lifecycle_ledger WHERE proposal_id=rid AND kind='cash_convert')<>p.quantity OR NOT EXISTS(SELECT 1 FROM ty_leave_lifecycle_cash_revision WHERE proposal_id=rid)))OR(p.status IN('rejected','cancelled')AND(SELECT coalesce(sum(quantity),0)FROM ty_leave_lifecycle_ledger WHERE proposal_id=rid AND kind='cash_release')<>p.quantity)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='现金转换状态、预占、耗用或义务不守恒';END IF;
 END IF;
 RETURN NEW;END;$$;
CREATE CONSTRAINT TRIGGER trg_ty_leave_lifecycle_conservation AFTER INSERT OR UPDATE ON ty_leave_lifecycle_proposal DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_lifecycle_conservation();
CREATE CONSTRAINT TRIGGER trg_ty_leave_lifecycle_ledger_conservation AFTER INSERT ON ty_leave_lifecycle_ledger DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_lifecycle_conservation();

CREATE FUNCTION fn_ty_leave_lifecycle_lot_conservation() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_id bigint;v_l ty_leave_lot%ROWTYPE;v_granted numeric;v_expired numeric;v_advanced numeric;v_in numeric;v_out numeric;v_convert numeric;v_cash numeric;v_held numeric;v_allocated numeric;v_taken numeric;v_extension date;v_protection text;BEGIN
 IF TG_TABLE_NAME='ty_leave_lot' THEN v_id:=NEW.id;ELSE v_id:=NEW.lot_id;END IF;
 SELECT * INTO v_l FROM ty_leave_lot WHERE id=v_id;
 SELECT coalesce(sum(delta)FILTER(WHERE event_kind<>'expire'),0),-coalesce(sum(delta)FILTER(WHERE event_kind='expire'),0) INTO v_granted,v_expired FROM ty_leave_event WHERE lot_id=v_id;
 SELECT coalesce(sum(quantity)FILTER(WHERE state='held'),0),coalesce(sum(quantity)FILTER(WHERE state='allocated'),0),coalesce(sum(quantity)FILTER(WHERE state='taken'),0) INTO v_held,v_allocated,v_taken FROM ty_leave_allocation WHERE lot_id=v_id;
 SELECT coalesce(sum(CASE kind WHEN 'advance' THEN quantity WHEN 'repay_loan' THEN -quantity ELSE 0 END),0),
 coalesce(sum(quantity)FILTER(WHERE kind IN('carry_in','repay_loan')),0),coalesce(sum(quantity)FILTER(WHERE kind IN('carry_out','repay_source')),0),
 coalesce(sum(quantity)FILTER(WHERE kind IN('cash_convert','comp_cash')),0),coalesce(sum(CASE kind WHEN 'cash_hold' THEN quantity WHEN 'cash_release' THEN -quantity WHEN 'cash_convert' THEN -quantity ELSE 0 END),0)
 INTO v_advanced,v_in,v_out,v_convert,v_cash FROM ty_leave_lifecycle_ledger WHERE lot_id=v_id;
 v_cash:=v_cash+coalesce((SELECT cash_reserved FROM ty_leave_lifecycle_lot_baseline WHERE lot_id=v_id),0);
 IF v_l.granted<>v_granted OR v_l.expired<>v_expired OR v_l.held<>v_held OR v_l.allocated<>v_allocated OR v_l.taken<>v_taken OR v_l.advanced<>v_advanced OR v_l.transferred_in<>v_in OR v_l.transferred_out<>v_out OR v_l.converted<>v_convert OR v_l.cash_reserved<>v_cash THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='权益批次必须与不可变流水和实际占用逐项守恒';END IF;
 SELECT max(e.new_expires_on)INTO v_extension FROM ty_leave_extension e JOIN ty_leave_lifecycle_proposal p ON p.id=e.proposal_id WHERE e.lot_id=v_id AND p.status='approved';
 IF coalesce(v_l.effective_expires_on,v_l.expires_on)IS DISTINCT FROM coalesce(v_extension,v_l.expires_on)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='生效期限必须有不可变延期核准依据，不能直接改日期或恢复旧期限';END IF;
 SELECT CASE WHEN kind='earned_overtime'OR root_key LIKE 'ot:%'THEN 'compensation'WHEN kind='advance'OR root_key LIKE 'advance:%'THEN 'advance'ELSE 'none'END INTO v_protection FROM ty_leave_credit_origin WHERE lot_id=v_id;
 IF v_l.source_protection<>coalesce(v_protection,'none')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='原加班和预支来源保护不可关闭';END IF;RETURN NEW;END;$$;
CREATE CONSTRAINT TRIGGER trg_ty_leave_life_lot_conservation AFTER INSERT OR UPDATE ON ty_leave_lot DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_lifecycle_lot_conservation();
CREATE CONSTRAINT TRIGGER trg_ty_leave_life_ledger_lot_conservation AFTER INSERT ON ty_leave_lifecycle_ledger DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_lifecycle_lot_conservation();

CREATE FUNCTION fn_ty_leave_overtime_conservation() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_id bigint;v_s ty_leave_overtime_source%ROWTYPE;v_cash numeric;v_comp numeric;v_generated numeric;v_returned numeric;BEGIN
 IF TG_TABLE_NAME='ty_leave_overtime_source' THEN v_id:=NEW.id;ELSE v_id:=NEW.source_id;END IF;
 SELECT * INTO v_s FROM ty_leave_overtime_source WHERE id=v_id;
 SELECT coalesce(sum(cash_basis_delta),0),coalesce(sum(comp_basis_delta),0),coalesce(sum(comp_quantity_delta),0) INTO v_cash,v_comp,v_generated FROM ty_leave_overtime_allocation WHERE source_id=v_id;
 SELECT coalesce(sum(basis_minutes),0)INTO v_returned FROM ty_leave_comp_cash_conversion WHERE source_id=v_id;
 IF v_s.cash_basis<>v_s.initial_cash_basis+v_cash+v_returned OR v_s.comp_basis<>v_s.initial_comp_basis+v_comp-v_returned OR v_s.comp_generated<>v_generated OR v_s.comp_returned_basis<>v_returned OR v_s.comp_generated*v_s.ratio_denominator>(v_s.comp_basis+v_s.comp_returned_basis-v_s.initial_comp_basis)*v_s.ratio_numerator OR NOT EXISTS(SELECT 1 FROM ty_leave_overtime_revision WHERE source_id=v_id AND revision=v_s.latest_revision AND (facts->>'verified_minutes')::numeric=v_s.verified_minutes) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='加班基础分配、源修订和已生成兑换量不守恒';END IF;RETURN NEW;END;$$;
CREATE CONSTRAINT TRIGGER trg_ty_leave_ot_conservation AFTER INSERT OR UPDATE ON ty_leave_overtime_source DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_overtime_conservation();
CREATE CONSTRAINT TRIGGER trg_ty_leave_ot_allocation_conservation AFTER INSERT ON ty_leave_overtime_allocation DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_overtime_conservation();
CREATE CONSTRAINT TRIGGER trg_ty_leave_ot_cash_conservation AFTER INSERT ON ty_leave_comp_cash_conversion DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_overtime_conservation();

CREATE FUNCTION fn_ty_leave_advance_conservation() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE v_id bigint;v_a ty_leave_advance%ROWTYPE;v_repaid numeric;BEGIN
 IF TG_TABLE_NAME='ty_leave_advance' THEN v_id:=NEW.id;ELSE v_id:=NEW.advance_id;END IF;SELECT * INTO v_a FROM ty_leave_advance WHERE id=v_id;
 SELECT coalesce(sum(quantity),0) INTO v_repaid FROM ty_leave_advance_repayment WHERE advance_id=v_id;
 IF v_a.outstanding<>v_a.original_quantity-v_repaid THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='预支未清量与清偿不可变流水不守恒';END IF;RETURN NEW;END;$$;
CREATE CONSTRAINT TRIGGER trg_ty_leave_advance_conservation AFTER INSERT OR UPDATE ON ty_leave_advance DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_advance_conservation();
CREATE CONSTRAINT TRIGGER trg_ty_leave_repayment_conservation AFTER INSERT ON ty_leave_advance_repayment DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_advance_conservation();

CREATE FUNCTION fn_ty_leave_lifecycle_identity() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='生命周期来源及债务历史不可删除';END IF;
 IF TG_TABLE_NAME='ty_leave_overtime_source' THEN
  IF(to_jsonb(NEW)-ARRAY['latest_revision','verified_minutes','cash_basis','comp_basis','comp_generated','comp_returned_basis'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['latest_revision','verified_minutes','cash_basis','comp_basis','comp_generated','comp_returned_basis'])THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='加班事实根、已结基线、未知占用及计价身份不可改写';END IF;
 ELSIF TG_TABLE_NAME='ty_leave_lifecycle_cash_obligation' THEN
  IF NEW.account_id<>OLD.account_id OR NEW.root_key<>OLD.root_key OR NEW.currency<>OLD.currency OR NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='现金义务必须同根连续版本';END IF;
 ELSIF TG_TABLE_NAME='ty_leave_advance' THEN
  IF(to_jsonb(NEW)-ARRAY['outstanding','status'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['outstanding','status'])THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='预支原批准和身份不可改写';END IF;
 END IF;RETURN NEW;END;$$;
CREATE TRIGGER trg_ty_leave_ot_identity BEFORE UPDATE OR DELETE ON ty_leave_overtime_source FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_lifecycle_identity();
CREATE TRIGGER trg_ty_leave_cash_obligation_identity BEFORE UPDATE OR DELETE ON ty_leave_lifecycle_cash_obligation FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_lifecycle_identity();
CREATE TRIGGER trg_ty_leave_advance_identity BEFORE UPDATE OR DELETE ON ty_leave_advance FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_lifecycle_identity();

CREATE UNIQUE INDEX uq_ty_leave_current_cash_qualification ON ty_leave_cash_qualification(account_id,root_key)WHERE status='approved';
CREATE FUNCTION fn_ty_leave_cash_document_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='现金核定及占用历史不可删除';END IF;
 IF TG_TABLE_NAME='ty_leave_cash_qualification' THEN
  IF(to_jsonb(NEW)-ARRAY['status','reserved_days','converted_days'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['status','reserved_days','converted_days']) OR(OLD.status='superseded' AND NEW IS DISTINCT FROM OLD)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='现金资格正文和旧修订不得改写';END IF;
 ELSE
  IF(to_jsonb(NEW)-'status')IS DISTINCT FROM(to_jsonb(OLD)-'status')OR OLD.status<>'held' OR NEW.status NOT IN('converted','released')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='现金占用只可原笔确认或释放';END IF;
 END IF;RETURN NEW;END;$$;
CREATE TRIGGER trg_ty_leave_cash_qualification_guard BEFORE UPDATE OR DELETE ON ty_leave_cash_qualification FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_cash_document_guard();
CREATE TRIGGER trg_ty_leave_cash_reservation_guard BEFORE UPDATE OR DELETE ON ty_leave_cash_reservation FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_cash_document_guard();

CREATE FUNCTION fn_ty_check_leave_cash(p_account bigint,p_root text)RETURNS void LANGUAGE plpgsql AS $$
DECLARE v_o ty_leave_lifecycle_cash_obligation%ROWTYPE;v_s ty_leave_overtime_source%ROWTYPE;v_r record;v_n numeric:=0;v_d numeric:=1;v_g numeric;v_cn numeric;v_cd numeric;v_covered numeric:=0;v_gross numeric;BEGIN
 IF p_root LIKE 'ot:%:cash' THEN
  SELECT * INTO v_s FROM ty_leave_overtime_source WHERE id=split_part(p_root,':',2)::bigint AND account_id=p_account;
  IF v_s.id IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='现金义务没有原加班补偿根';END IF;
  v_n:=(v_s.cash_basis-v_s.initial_cash_basis)*10000*v_s.cash_unit_rate*10000000000;v_d:=100000000000000;
 ELSIF p_root LIKE 'annual:%:cash' THEN
  FOR v_r IN SELECT r.quantity,c.daily_rate_numerator,c.daily_rate_denominator,c.normal_daily_covered FROM ty_leave_cash_reservation r JOIN ty_leave_cash_qualification c ON c.id=r.qualification_id WHERE c.account_id=p_account AND c.root_key||':cash'=p_root AND r.status='converted' LOOP
   v_cn:=v_r.quantity*10000*v_r.daily_rate_numerator;v_cd:=10000*v_r.daily_rate_denominator;v_n:=v_n*v_cd+v_cn*v_d;v_d:=v_d*v_cd;v_g:=gcd(v_n,v_d);v_n:=div(v_n,v_g);v_d:=div(v_d,v_g);v_covered:=v_covered+v_r.quantity*v_r.normal_daily_covered;
  END LOOP;
 ELSE RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='不认识的生命周期现金义务根';END IF;
 SELECT * INTO v_o FROM ty_leave_lifecycle_cash_obligation WHERE account_id=p_account AND root_key=p_root;
 IF v_o.id IS NULL AND v_n=0 THEN RETURN;END IF;
 v_gross:=(div(v_n*10000,v_d)+CASE WHEN mod(v_n*10000,v_d)*2>=v_d THEN 1 ELSE 0 END)/10000;
 IF v_o.id IS NULL OR v_o.gross_numerator::numeric*v_d<>v_n*v_o.gross_denominator::numeric OR v_o.gross_target<>v_gross OR v_o.normal_covered<>round(v_covered,4)OR NOT EXISTS(SELECT 1 FROM ty_leave_lifecycle_cash_revision x JOIN ty_leave_lifecycle_proposal p ON p.id=x.proposal_id WHERE x.obligation_id=v_o.id AND x.revision=v_o.revision AND p.status='approved' AND p.account_id=p_account AND x.gross_target=v_o.gross_target AND x.normal_covered=v_o.normal_covered AND x.gross_numerator=v_o.gross_numerator AND x.gross_denominator=v_o.gross_denominator)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='现金义务必须对应已确认原量、精确计价和唯一批准修订';END IF;
END;$$;
CREATE FUNCTION fn_ty_leave_cash_conservation()RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_account bigint;v_root text;v_c ty_leave_cash_qualification%ROWTYPE;v_o ty_leave_lifecycle_cash_obligation%ROWTYPE;v_held numeric;v_converted numeric;BEGIN
 IF TG_TABLE_NAME='ty_leave_lifecycle_cash_obligation' THEN v_account:=NEW.account_id;v_root:=NEW.root_key;
 ELSIF TG_TABLE_NAME='ty_leave_lifecycle_cash_revision' THEN SELECT * INTO v_o FROM ty_leave_lifecycle_cash_obligation WHERE id=NEW.obligation_id;v_account:=v_o.account_id;v_root:=v_o.root_key;
 ELSIF TG_TABLE_NAME='ty_leave_overtime_source' THEN v_account:=NEW.account_id;v_root:='ot:'||NEW.id||':cash';
 ELSE
  IF TG_TABLE_NAME='ty_leave_cash_qualification' THEN SELECT * INTO v_c FROM ty_leave_cash_qualification WHERE id=NEW.id;ELSE SELECT * INTO v_c FROM ty_leave_cash_qualification WHERE id=NEW.qualification_id;END IF;
  v_account:=v_c.account_id;v_root:=v_c.root_key||':cash';
  SELECT * INTO v_c FROM ty_leave_cash_qualification WHERE account_id=v_account AND root_key||':cash'=v_root AND status='approved';
  IF v_c.id IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='现金资格缺少当前核定修订';END IF;
  SELECT coalesce(sum(r.quantity)FILTER(WHERE r.status='held'),0),coalesce(sum(r.quantity)FILTER(WHERE r.status='converted'),0)INTO v_held,v_converted FROM ty_leave_cash_reservation r JOIN ty_leave_cash_qualification c ON c.id=r.qualification_id WHERE c.account_id=v_account AND c.root_key=v_c.root_key;
  IF v_c.reserved_days<>v_held OR v_c.converted_days<>v_converted THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='现金资格修订不得重置预占或已转换量';END IF;
 END IF;
 PERFORM fn_ty_check_leave_cash(v_account,v_root);RETURN NEW;END;$$;
CREATE CONSTRAINT TRIGGER trg_ty_leave_cash_obligation_conservation AFTER INSERT OR UPDATE ON ty_leave_lifecycle_cash_obligation DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_cash_conservation();
CREATE CONSTRAINT TRIGGER trg_ty_leave_cash_revision_conservation AFTER INSERT ON ty_leave_lifecycle_cash_revision DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_cash_conservation();
CREATE CONSTRAINT TRIGGER trg_ty_leave_ot_cash_obligation_conservation AFTER INSERT OR UPDATE ON ty_leave_overtime_source DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_cash_conservation();
CREATE CONSTRAINT TRIGGER trg_ty_leave_cash_qualification_conservation AFTER INSERT OR UPDATE ON ty_leave_cash_qualification DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_cash_conservation();
CREATE CONSTRAINT TRIGGER trg_ty_leave_cash_reservation_conservation AFTER INSERT OR UPDATE ON ty_leave_cash_reservation DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_cash_conservation();

CREATE FUNCTION fn_ty_leave_source_event_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_o ty_leave_credit_origin%ROWTYPE;BEGIN
 SELECT * INTO v_o FROM ty_leave_credit_origin WHERE lot_id=NEW.lot_id;
 IF v_o.lot_id IS NULL THEN RETURN NEW;END IF;
 IF v_o.kind='earned_overtime' THEN
  IF NEW.event_kind<>'grant' OR NEW.event_key<>'ot-allocation:'||v_o.proposal_id OR(NEW.payload->>'lifecycle_proposal_id')::bigint IS DISTINCT FROM v_o.proposal_id OR NOT EXISTS(SELECT 1 FROM ty_leave_overtime_allocation WHERE proposal_id=v_o.proposal_id AND lot_id=NEW.lot_id AND comp_quantity_delta=NEW.delta)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='真实加班生成量须回原补偿来源处理，不能通用增发或清零';END IF;
 ELSIF v_o.kind='advance' OR v_o.kind='carry' THEN
  IF NEW.event_kind<>'expire' OR v_o.kind='advance' OR v_o.root_key LIKE 'ot:%'OR v_o.root_key LIKE 'advance:%' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='接续或预支权益不能再当独立新授予、兑付或自动作废';END IF;
 END IF;RETURN NEW;END;$$;
CREATE TRIGGER trg_ty_leave_source_event_guard BEFORE INSERT ON ty_leave_event FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_source_event_guard();

CREATE FUNCTION fn_ty_leave_recurring_conservation()RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_id bigint;v_o ty_leave_recurring_occurrence%ROWTYPE;v_auth ty_leave_recurring_authorization%ROWTYPE;v_link record;v_total numeric;v_older numeric;v_limit numeric;v_count integer;BEGIN
 IF TG_TABLE_NAME='ty_leave_recurring_occurrence' THEN v_id:=NEW.id;ELSE v_id:=NEW.occurrence_id;END IF;
 SELECT * INTO v_o FROM ty_leave_recurring_occurrence WHERE id=v_id;
 SELECT * INTO v_auth FROM ty_leave_recurring_authorization WHERE id=v_o.authorization_id;
 IF v_o.account_id<>v_auth.account_id OR v_o.work_date<v_auth.valid_from OR v_o.work_date>=v_auth.valid_to OR v_o.root_key<>v_auth.stable_key||':'||v_o.work_date||':'||v_o.slot_key THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='周期发生根、实际关系和授权日期不一致';END IF;
 IF v_o.request_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM ty_leave_recurring_request_link WHERE occurrence_id=v_id AND request_id=v_o.request_id AND sequence=v_o.request_sequence)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='周期申请须保留唯一不可变提交血缘';END IF;
 SELECT count(*)INTO v_count FROM ty_leave_recurring_request_link x JOIN ty_leave_request r ON r.id=x.request_id WHERE x.occurrence_id=v_id AND r.status IN('pending','approved','taken');IF v_count>1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='同一周期发生根最多一份有效申请或已休';END IF;
 FOR v_link IN SELECT x.*,r.account_id request_account,r.employment_id,r.starts_at,r.ends_at,r.facts,r.status request_status,r.approved_by request_approved_by,a.account_id authorization_account,a.employment_id authorization_employment,a.scheme_id,p.approved_by original_approved_by,p.created_by authorization_requester FROM ty_leave_recurring_request_link x JOIN ty_leave_request r ON r.id=x.request_id JOIN ty_leave_recurring_authorization a ON a.id=x.authorization_id JOIN ty_leave_lifecycle_proposal p ON p.id=a.proposal_id WHERE x.occurrence_id=v_id LOOP
  IF v_link.request_account<>v_o.account_id OR v_link.authorization_account<>v_o.account_id OR v_link.original_requester_id<>v_link.authorization_requester OR v_link.employment_id<>v_link.authorization_employment OR(v_link.facts->>'minutes')::numeric IS NULL OR(v_link.facts->>'minutes')::numeric<=0 OR(v_link.facts->>'minutes')::numeric>coalesce((SELECT (rules->'recurring'->>'max_minutes_per_occurrence')::numeric FROM ty_leave_scheme WHERE id=v_link.scheme_id),60)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='周期申请须保留原申请人、同关系已核排班计量且不超授权';END IF;
  IF v_link.approval_mode='inherited_authorization'AND(v_link.inherited_approved_by IS DISTINCT FROM v_link.original_approved_by OR v_link.request_approved_by IS DISTINCT FROM v_link.original_approved_by OR v_link.request_status='pending')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='周期继承审批必须引用原授权真实批准人，不是执行人冒签';END IF;
 END LOOP;
 SELECT a.* INTO v_auth FROM ty_leave_recurring_authorization a WHERE a.account_id=v_o.account_id AND a.stable_key=v_auth.stable_key AND a.valid_from<=v_o.work_date AND a.valid_to>v_o.work_date ORDER BY a.revision DESC LIMIT 1;
 SELECT coalesce((rules->'recurring'->>'max_minutes_per_day')::numeric,(rules->'recurring'->>'max_minutes_per_occurrence')::numeric,60)INTO v_limit FROM ty_leave_scheme WHERE id=v_auth.scheme_id;
 SELECT coalesce(sum((r.facts->>'minutes')::numeric),0),coalesce(sum((r.facts->>'minutes')::numeric)FILTER(WHERE a.revision<v_auth.revision),0)INTO v_total,v_older FROM ty_leave_recurring_request_link x JOIN ty_leave_request r ON r.id=x.request_id JOIN ty_leave_recurring_occurrence o ON o.id=x.occurrence_id JOIN ty_leave_recurring_authorization a ON a.id=x.authorization_id WHERE o.account_id=v_o.account_id AND o.work_date=v_o.work_date AND a.stable_key=v_auth.stable_key AND r.status IN('pending','approved','taken');
 IF v_total>greatest(v_limit,v_older)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='周期根每日总计量不能通过换时窗键或修订重复领取';END IF;RETURN NEW;END;$$;
CREATE CONSTRAINT TRIGGER trg_ty_leave_recurring_occurrence_conservation AFTER INSERT OR UPDATE ON ty_leave_recurring_occurrence DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_recurring_conservation();
CREATE CONSTRAINT TRIGGER trg_ty_leave_recurring_link_conservation AFTER INSERT ON ty_leave_recurring_request_link DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_recurring_conservation();
CREATE FUNCTION fn_ty_leave_recurring_request_required()RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_r ty_leave_request%ROWTYPE;BEGIN SELECT * INTO v_r FROM ty_leave_request WHERE id=NEW.id;
 IF EXISTS(SELECT 1 FROM ty_leave_scheme WHERE id=v_r.scheme_id AND(rules->'recurring'->>'enabled')::boolean)AND NOT EXISTS(SELECT 1 FROM ty_leave_recurring_request_link WHERE request_id=v_r.id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='周期申请必须由授权发生入口在同一事务写入不可变来源链，不能通用API单独落单';END IF;RETURN NEW;END;$$;
CREATE CONSTRAINT TRIGGER trg_ty_leave_recurring_request_required AFTER INSERT ON ty_leave_request DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_leave_recurring_request_required();
